-- V14: 补齐健康养生、休闲娱乐两大类课程（此前仅有分类无课程）
-- 课程 18-21：运动锻炼 / 饮食营养 / 影音娱乐 / 兴趣爱好 各一门
-- 内容沿用五段式图文结构（<h3>+<p>），封面为自包含 SVG（course-18..21.svg）

INSERT INTO `course_info` (`id`, `category_id`, `title`, `cover`, `content`, `video_url`, `intro`, `duration`, `points_reward`, `status`, `province`, `city`, `district`)
SELECT 18, 41, '晨练散步与太极入门', '/uploads/images/course-18.svg',
'<h3>一、为什么要坚持晨练</h3><p>人到老年，肌肉流失、腿脚发沉是自然规律，但越不动越没劲。坚持每天散步、打打太极，能增强腿部力量、改善平衡、帮助睡眠，还能在公园认识老伙伴，心情也跟着敞亮。</p><h3>二、晨练前的准备</h3><p>1. 穿防滑运动鞋和宽松透气的衣裤，天冷加外套、戴帽子；</p><p>2. 出门前喝一小杯温水，随身带上手机和几张零钱；</p><p>3. 有高血压、心脏病的老人先量血压，感觉头晕胸闷就当天不要勉强；</p><p>4. 告诉家人去哪个公园、大概几点回来。</p><h3>三、适合老年人的锻炼方法</h3><p>1. 散步：先慢走五分钟热身，再中等速度走二十到三十分钟，走到微微出汗、能说话不能唱歌的强度正好；</p><p>2. 太极拳：跟社区晨练队学二十四式简化太极拳，动作缓慢、处处用意不用力，跟着老师比看视频学得快；</p><p>3. 八段锦：八个简单动作十来分钟做完，风雨天在家也能练。</p><h3>四、运动安全注意事项</h3><p>1. 时间选太阳出来后的早晨或傍晚，空腹和刚吃完饭都不宜运动；</p><p>2. 循序渐进，累了就休息，不求和别人比步数；</p><p>3. 雨雪天、雾霾天改在室内活动，路滑防跌倒是第一位；</p><p>4. 运动中若心慌、腿软，立即坐下休息，随身药卡和联系电话要带好。</p><h3>五、常见问题</h3><p>问：每天走多少步合适？答：六千步左右即可，不必追求一万步，关节不好的老人减半。</p><p>问：晨练回来膝盖疼怎么办？答：减少时长、放慢速度，疼痛持续就到医院检查，暂时改练八段锦。</p>', NULL,
'学习适合老年人的散步与太极锻炼方法，掌握晨练安全要点，在家门口就能把身体练结实。', 8, 20, 1, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `course_info` WHERE `id` = 18);

INSERT INTO `course_info` (`id`, `category_id`, `title`, `cover`, `content`, `video_url`, `intro`, `duration`, `points_reward`, `status`, `province`, `city`, `district`)
SELECT 19, 42, '三餐营养与饮食安全', '/uploads/images/course-19.svg',
'<h3>一、为什么上了年纪更要讲究吃</h3><p>年纪大了牙口松、消化慢、味觉变淡，很多老人吃得越来越咸、越来越单一。吃对了，血压血糖平稳、腿脚有劲；吃错了，营养跟不上还容易吃出毛病。学会一日三餐怎么安排，是健康长寿的第一门课。</p><h3>二、三餐怎么安排</h3><p>1. 早餐要吃好：一个鸡蛋、一杯牛奶或豆浆、一两主食，再加点小菜；</p><p>2. 午餐要吃饱：主食一碗，荤素搭配，鱼、瘦肉、豆腐换着来；</p><p>3. 晚餐要吃少：七分饱，清淡易消化，睡前两三个小时不再进食；</p><p>4. 两餐之间可加一次水果或酸奶，血糖高的老人选苹果、柚子等低糖水果。</p><h3>三、营养搭配要点</h3><p>1. 每天一斤蔬菜、半斤水果，深绿色蔬菜占一半；</p><p>2. 每周吃两三次鱼，豆制品天天有，牙不好就把肉炖烂、剁碎；</p><p>3. 每天喝够六七杯水，别等口渴才喝；</p><p>4. 盐一天不超过一瓶盖（约5克），少吃咸菜、腊肉、酱料。</p><h3>四、饮食安全要记牢</h3><p>1. 剩菜及时放冰箱，吃前彻底加热，绿叶菜、凉拌菜过夜就倒掉；</p><p>2. 发霉的花生、玉米、水果整个丢掉，切掉坏的部分也不能吃；</p><p>3. 冰箱不是保险箱，冷藏超过两三天的食物不再食用；</p><p>4. 保健食品不是药，不能替代正常吃饭和医生开的药。</p><h3>五、常见问题</h3><p>问：没牙怎么吃肉？答：做成肉末、肉丸、清蒸鱼，营养不打折。</p><p>问：怕血糖高，主食怎么吃？答：粗细搭配，白米里加燕麦、小米、糙米，先吃菜再吃饭，饭后走一走。</p>', NULL,
'掌握老年人一日三餐的营养搭配与饮食安全常识，吃得健康、吃得放心。', 8, 20, 1, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `course_info` WHERE `id` = 19);

INSERT INTO `course_info` (`id`, `category_id`, `title`, `cover`, `content`, `video_url`, `intro`, `duration`, `points_reward`, `status`, `province`, `city`, `district`)
SELECT 20, 51, '刷短视频与线上看戏曲', '/uploads/images/course-20.svg',
'<h3>一、短视频和戏曲能带来什么</h3><p>想听的豫剧、越剧、黄梅戏，想看的老电影、养生讲座，手机上点一点就能看，还能跟着老票友学唱两段。儿女上班不在家，一部手机就是随身的收音机和电视机，日子过得有声有色。</p><h3>二、怎么看短视频</h3><p>1. 打开微信，搜索“视频号”或使用抖音、快手等正规应用；</p><p>2. 在搜索框输入想看的内容，如“京剧选段”“太极教学”；</p><p>3. 上下滑动切换视频，点红心是喜欢，点箭头能转发给老朋友；</p><p>4. 看到好的戏曲账号点“关注”，下次打开就能接着看。</p><h3>三、线上看戏曲和大戏</h3><p>1. 在视频号、抖音搜索“戏曲频道”“某某剧团”官方账号；</p><p>2. 各地戏曲剧院常在网上直播演出，准时进入就能免费看大戏；</p><p>3. 电视端可让子女帮忙安装戏曲频道应用，投屏到大电视更过瘾。</p><h3>四、控制时间别贪看</h3><p>1. 每次看半小时就起身活动、远眺放松眼睛；</p><p>2. 睡前一小时少看手机，屏幕太亮影响睡眠；</p><p>3. 手机看视频费流量，尽量连家里无线网。</p><h3>五、安全提醒</h3><p>1. 短视频里的“直播间卖药”“低价保健鞋”别轻信，购物让子女把关；</p><p>2. 不给陌生人打赏、不点视频里的红包链接和抽奖；</p><p>3. 不转发未经核实的“养生秘诀”“震惊消息”，防止帮谣言扩散。</p>', NULL,
'学会用手机刷短视频、线上看戏曲大戏，丰富日常娱乐，同时避开直播购物与打赏陷阱。', 8, 20, 1, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `course_info` WHERE `id` = 20);

INSERT INTO `course_info` (`id`, `category_id`, `title`, `cover`, `content`, `video_url`, `intro`, `duration`, `points_reward`, `status`, `province`, `city`, `district`)
SELECT 21, 52, '手机听书与新闻浏览', '/uploads/images/course-21.svg',
'<h3>一、听书和看新闻的好处</h3><p>眼睛花了看小字费劲，但耳朵还灵。手机听书能把小说、评书、养生知识“念”给您听，做家务、散步时都能听；每天看看正规新闻，了解国家大事和本地民生消息，头脑灵活不落伍。</p><h3>二、用手机听书</h3><p>1. 让子女帮忙安装“喜马拉雅”“番茄畅听”或“微信听书”；</p><p>2. 在搜索框输入想听的内容，如“单田芳评书”“老人保健知识”；</p><p>3. 点开节目按播放键即可收听，音量用手机侧面的按键调节；</p><p>4. 听到哪里退出，下次打开会记住位置接着听；</p><p>5. 连接蓝牙音箱或小收音机外放，声音更清楚。</p><h3>三、看正规新闻</h3><p>1. 推荐“央视新闻”“人民日报”或本省官方新闻客户端；</p><p>2. 字太小可在“我的—设置—字体大小”里调大；</p><p>3. 找不准的字可以长按选择“朗读”，让手机读给您听。</p><h3>四、护眼小常识</h3><p>1. 每看二十分钟闭眼休息或望望远处；</p><p>2. 夜里开灯看，黑屋子看屏幕最伤眼；</p><p>3. 手机可开启“护眼模式”，屏幕变柔和。</p><h3>五、辨别消息真伪</h3><p>只看正规媒体新闻，家庭群转来的“紧急通知”“惊天秘密”先让子女核实；记不准的消息到“中国互联网联合辟谣平台”查一查，不造谣、不信谣、不传谣。</p>', NULL,
'学会手机听书、听评书和浏览正规新闻，保护眼睛又能随时了解天下大事。', 8, 20, 1, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `course_info` WHERE `id` = 21);
